class Dispatcher:
    """Sends each customer's events to that customer's webhook URL."""

    def __init__(self, send):
        self.send = send  # send(url, event): makes the HTTP request
        self.handlers = {}

    def register(self, customers):
        """Add webhooks for (customer_id, url) pairs. Called again whenever customers sign up."""
        for customer_id, url in customers:
            self.handlers[customer_id] = lambda event: self.send(url, event)

    def dispatch(self, customer_id, event):
        self.handlers[customer_id](event)

